package com.sih.gap.entity; import jakarta.persistence.*; import java.time.*; import lombok.*; @Entity @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class QueueTicket{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false)String tenantId;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="patient_id",nullable=false)Patient patient;@Column(nullable=false,unique=true)String ticketNumber;@Column(nullable=false)String serviceArea;@Enumerated(EnumType.STRING)@Column(nullable=false)Acuity acuity;@Enumerated(EnumType.STRING)@Column(nullable=false)Status status;String chiefComplaint;Integer painScore;Integer oxygenSaturation;Integer heartRate;String assignedClinicianId;OffsetDateTime checkedInAt;OffsetDateTime calledAt;OffsetDateTime completedAt;@PrePersist void p(){if(tenantId==null)tenantId=com.sih.shared.tenant.TenantContext.getCurrentTenant();if(checkedInAt==null)checkedInAt=OffsetDateTime.now();if(status==null)status=Status.WAITING;}public enum Acuity{P1_IMMEDIATE,P2_VERY_URGENT,P3_URGENT,P4_STANDARD,P5_ROUTINE}public enum Status{WAITING,CALLED,IN_CONSULTATION,COMPLETED,CANCELLED}}